            try:
                items = [next(it) for it in iters]
            except StopIteration:
                # Check if all exhausted
                if all(not hasattr(it, '__length_hint__') for it in iters):
                    return
                raise UnequalIterablesError('Iterables have unequal length.')
            else:
                yield tuple(items)
